// Generated by guide/build.js from guide/pages/*.html. Change the pages, then run npm run guide.
import { LightningElement, api } from 'lwc';

/** Shows one Grid Guide page, by id, opened at a section. */
export default class GuideContent extends LightningElement {
    /** The page's id, from c/guideCatalog. */
    @api page;
    /** The section to open it at, or nothing for the top. */
    @api section;

    get isWelcome() {
        return this.page === 'welcome';
    }

    get isStart() {
        return this.page === 'start';
    }

    get isConfigure() {
        return this.page === 'configure';
    }

    get isFeatures() {
        return this.page === 'features';
    }

    get isUsing() {
        return this.page === 'using';
    }

    get isTutorials() {
        return this.page === 'tutorials';
    }

    get isTutorialPipeline() {
        return this.page === 'tutorial-pipeline';
    }

    get isTutorialService() {
        return this.page === 'tutorial-service';
    }

    get isTutorialAccounts() {
        return this.page === 'tutorial-accounts';
    }

    get isTutorialContacts() {
        return this.page === 'tutorial-contacts';
    }

    get isTutorialCleanup() {
        return this.page === 'tutorial-cleanup';
    }

    get isTutorialGroups() {
        return this.page === 'tutorial-groups';
    }

    get isTutorialAssets() {
        return this.page === 'tutorial-assets';
    }

    get isTutorialLeads() {
        return this.page === 'tutorial-leads';
    }

    get isReference() {
        return this.page === 'reference';
    }
}
